INSERT INTO "gates" VALUES('G01','scanner','Rolling polynomial, min/max boundary and byte-carving gate.');
INSERT INTO "gates" VALUES('G02','worker','Strict sequence, parent, payload assertion and append gate.');
INSERT INTO "gates" VALUES('G03','boundary','Registered payload and metadata verification immediately before invocation.');
INSERT INTO "gates" VALUES('G04','admission','Queue-count, pending-byte and immutable-ledger reservation gate.');
INSERT INTO "gates" VALUES('G05','availability','Verifier availability checked both before and after hash work.');
INSERT INTO "gates" VALUES('G06','retention','Bounded receipt/event observations separate from immutable records.');
INSERT INTO "gates" VALUES('G07','snapshot','Immutable incoming snapshot before verification await.');
INSERT INTO "gates" VALUES('G08','lifecycle','Shared shielded shutdown task and cancellation cleanup.');
INSERT INTO "gates" VALUES('G09','deadline','Absolute transaction deadline checked before and after hashing.');
INSERT INTO "gates" VALUES('G10','pipeline','Bounded staging, structured sibling cancellation and source close.');
INSERT INTO "gates" VALUES('G11','schema','Strict scalar parsing in core and real MCP stdio.');
INSERT INTO "gates" VALUES('G12','quality','Executable structural, local speed and memory budgets.');
INSERT INTO "gates" VALUES('G13','evidence','Relational completeness, foreign keys and production source provenance gate.');
INSERT INTO "invariants" VALUES('I01','CDC-01','Every input byte appears once at its original byte offset.');
INSERT INTO "invariants" VALUES('I02','CDC-01','Packet splits do not change cuts or the independent polynomial oracle.');
INSERT INTO "invariants" VALUES('I03','GOV-01','Sequence gaps, duplicate commits and incorrect parents never advance the ledger.');
INSERT INTO "invariants" VALUES('I04','GOV-02','Committed block identity binds routing, source, session and predecessor.');
INSERT INTO "invariants" VALUES('I05','GOV-02','Only a committed matching payload can cross the invocation gate.');
INSERT INTO "invariants" VALUES('I06','GOV-03','Integrity mismatch clears context and causes zero additional effects.');
INSERT INTO "invariants" VALUES('I07','GOV-05','Unavailable or interrupted verification cannot return trust.');
INSERT INTO "invariants" VALUES('I08','GOV-04','Count and encoded-byte admission remain within configured bounds.');
INSERT INTO "invariants" VALUES('I09','GOV-06','Unknown/evicted receipt grants no trust; ledger identities remain available.');
INSERT INTO "invariants" VALUES('I10','GOV-07','An input mutation during await cannot replace bytes delivered to the tool.');
INSERT INTO "invariants" VALUES('I11','VV-01','Concurrent shutdown has one owner; pending bookkeeping reaches zero.');
INSERT INTO "invariants" VALUES('I12','GOV-05','An expired transaction cannot commit or be classified as tampering.');
INSERT INTO "invariants" VALUES('I13','GOV-08','Streaming preserves bytes with bounded staging and closes its source.');
INSERT INTO "invariants" VALUES('I14','GOV-08','A failed effect sink is invoked once; siblings cancel and source closes.');
INSERT INTO "invariants" VALUES('I15','VV-03','Malformed core/wire frames are rejected before immutable admission.');
INSERT INTO "invariants" VALUES('I16','VV-02','Runtime modules <=180 lines, functions <=60, decision nesting <=5, AST branch proxy <=20.');
INSERT INTO "invariants" VALUES('I17','VV-04','Scanner/ledger speed and memory satisfy explicit local catastrophic-regression ceilings.');
INSERT INTO "invariants" VALUES('I18','VV-05','Every finite Cartesian tuple and declared requirement retains referentially valid, source-bound assertion links.');
