INSERT INTO "obligations" VALUES('C009','metadata','I04','F09','G03','Rewritten source metadata with unchanged payload. Committed block identity binds routing, source, session and predecessor. Owner: Registered payload and metadata verification immediately before invocation.','{"outcome": "quarantined", "effects": [], "context": 0, "records": 1, "quarantined": 1}');
