INSERT INTO "obligations" VALUES('C012','block_hash','I04','F12','G03','Unregistered block identity. Committed block identity binds routing, source, session and predecessor. Owner: Registered payload and metadata verification immediately before invocation.','{"outcome": "quarantined", "effects": [], "context": 0, "quarantined": 1}');
