INSERT INTO "obligations" VALUES('C014','closed','I07','F14','G05','Verifier invoked after engine shutdown. Unavailable or interrupted verification cannot return trust. Owner: Verifier availability checked both before and after hash work.','{"outcome": "held", "effects": [], "context": 0, "records": 1, "quarantined": 0}');
INSERT INTO "obligations" VALUES('C015','hold_race','I07','F15','G05','Availability changes across hashing await. Unavailable or interrupted verification cannot return trust. Owner: Verifier availability checked both before and after hash work.','{"outcome": "held", "effects": [], "context": 0, "quarantined": 0}');
INSERT INTO "obligations" VALUES('C016','verifier_fault','I07','F16','G05','Unexpected verifier exception. Unavailable or interrupted verification cannot return trust. Owner: Verifier availability checked both before and after hash work.','{"outcome": "held", "effects": [], "context": 0, "quarantined": 0}');
INSERT INTO "obligations" VALUES('C017','verification_capacity','I07','F17','G05','Concurrent verification exceeds admission cap. Unavailable or interrupted verification cannot return trust. Owner: Verifier availability checked both before and after hash work.','{"outcome": "held", "verified": false, "quarantined": 0, "active_verifications": 0}');
INSERT INTO "obligations" VALUES('C018','cancel_verification','I07','F18','G08','Inbound verification cancelled while suspended. Unavailable or interrupted verification cannot return trust. Owner: Shared shielded shutdown task and cancellation cleanup.','{"outcome": "cancelled", "effects": [], "context": 0, "held": 1, "quarantined": 0, "active_verifications": 0}');
INSERT INTO "obligations" VALUES('C019','queue','I08','F19','G04','Queue count at cap plus one. Count and encoded-byte admission remain within configured bounds. Owner: Queue-count, pending-byte and immutable-ledger reservation gate.','{"outcome": "busy", "reason": "QUEUE_CAPACITY", "accepted": "verified", "records": 1, "pending_bytes": 0}');
INSERT INTO "obligations" VALUES('C020','pending_bytes','I08','F20','G04','Pending UTF-8 bytes at cap plus one. Count and encoded-byte admission remain within configured bounds. Owner: Queue-count, pending-byte and immutable-ledger reservation gate.','{"outcome": "busy", "reason": "PENDING_BYTE_CAPACITY", "accepted": "verified", "records": 1, "pending_bytes": 0}');
