INSERT INTO "supersessions" VALUES('pre-boundary','REG-04','current-unit','REG-04','GOV-05','Recheck availability after the hashing await before returning trust. The same assertion is retained unchanged; the passing run supersedes the failing run, not the requirement.');
INSERT INTO "supersessions" VALUES('pre-boundary','REG-05','current-unit','REG-05','GOV-05','Classify unexpected verifier exceptions as HOLD and clear receiving context. The same assertion is retained unchanged; the passing run supersedes the failing run, not the requirement.');
INSERT INTO "supersessions" VALUES('pre-api','REG-06','current-unit','REG-06','VV-03','StrictInt prevents MCP numeric coercion before the strict core parser. The same assertion is retained unchanged; the passing run supersedes the failing run, not the requirement.');
